function buildB2Vocab(entries: RawB2Tuple[]): VocabItem[] {
  const now = Date.now();
  return entries.map(([word, reading, partOfSpeech, meaningVi, topic, example, exampleVi, list], idx) => ({
    id: `en-b2-${idx + 1}`,
    language: 'en',
    word,
    reading,
    partOfSpeech,
    meaningVi,
    topic,
    levelTag: 'B2',
    example,
    exampleVi,
    srsState: 'new',
    easeFactor: 2.5,
    intervalDays: 0,
    repetitions: 0,
    nextReviewAt: now,
    customLists: [list],
  }));
}

export const ENGLISH_B2_EXTRA_VOCAB: VocabItem[] = buildB2Vocab(RAW_B2_ENTRIES);
